import { test, expect } from '@playwright/test';

test.describe('Landing footer and about links', () => {
  test('Footer and about page have no horizontal scroll on phone @mobile @prod-safe (#1afa56)', async ({ page }) => {
    const noHScroll = () =>
      page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth);
    const footerHashLinks = (footer: ReturnType<typeof page.getByRole>) =>
      footer.locator('a').evaluateAll((els) =>
        els.map((a) => a.getAttribute('href') ?? '').filter((h) => h === '#' || h.endsWith('/#')),
      );

    // 1. Open / as guest on a phone
    await page.goto('/');

    // 2. Scroll to the footer
    const footer = page.getByRole('contentinfo');
    await footer.scrollIntoViewIfNeeded();
    await expect(footer).toBeVisible();
    expect(await noHScroll(), 'no horizontal scroll on /').toBe(true);
    expect(await footerHashLinks(footer)).toHaveLength(0);

    // 3. Open /about and scroll through the founders block to the footer
    await page.goto('/about');
    const heading = page.getByRole('heading', { name: 'נעים להכיר!' });
    await heading.scrollIntoViewIfNeeded();
    await expect(heading).toBeVisible();
    const aboutFooter = page.getByRole('contentinfo');
    await aboutFooter.scrollIntoViewIfNeeded();
    await expect(aboutFooter).toBeVisible();
    expect(await noHScroll(), 'no horizontal scroll on /about').toBe(true);
    expect(await footerHashLinks(aboutFooter)).toHaveLength(0);
  });
});
